definitions.award_coins(text,text,jsonb):
CREATE OR REPLACE FUNCTION public.award_coins(p_source text, p_ref_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(awarded integer, balance integer, capped boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_amount    int;
  v_cap       int;
  v_live      boolean;
  v_today_cnt int;
  v_awarded   int := 0;
  v_capped    boolean := false;
  v_ref       text := p_ref_id;
  v_day       text := public.cairo_day()::text;
  v_days      int;
  v_wday      date;
  v_wname     text;
begin
  if v_uid is null then
    raise exception 'award_coins: لازم تكون داخل بحسابك';
  end if;

  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'award_coins: الزائر مايكسبش كوينز — سجّل حساب';
  end if;

  select amount, daily_cap, is_live
    into v_amount, v_cap, v_live
    from public.coin_source_rules
   where id = p_source;

  if not found then
    raise exception 'award_coins: مصدر مش معروف: %', p_source;
  end if;

  if not v_live then
    raise exception 'award_coins: المصدر % لسه مش شغّال', p_source;
  end if;

  case p_source
    when 'signup_bonus' then
      if not exists (select 1 from public.profiles p where p.id = v_uid) then
        raise exception 'award_coins: لا يوجد ملف شخصي للتسجيل';
      end if;
      v_ref := v_uid::text;

    when 'daily_login' then
      -- حضور نقي: السقف + الفهرس الفريد (user_id, source, يوم القاهرة) بيمنعوا التكرار.
      v_ref := v_day;

    when 'day_done' then
      if v_ref is null then
        raise exception 'award_coins: day_done محتاج معرّف اليوم';
      end if;
      if not exists (
        select 1 from public.study_days d
         where d.id::text = v_ref
           and d.user_id = v_uid
           and d.is_completed = true
      ) then
        raise exception 'award_coins: اليوم ده مش مخلّص على حسابك';
      end if;

    when 'goal_done' then
      if v_ref is null then
        raise exception 'award_coins: goal_done محتاج معرّف الهدف';
      end if;
      if not exists (
        select 1 from public.planner_goals g
         where g.id::text = v_ref
           and g.user_id = v_uid
           and g.is_done = true
      ) then
        raise exception 'award_coins: الهدف ده مش متعلّم على حسابك';
      end if;

    when 'badge' then
      if v_ref is null then
        raise exception 'award_coins: badge محتاج مرجع الفصل';
      end if;
      if not exists (
        select 1 from public.badges b
         where b.user_id = v_uid
           and b.config_id::text     = split_part(v_ref, ':', 1)
           and b.chapter_number::text = split_part(v_ref, ':', 2)
      ) then
        raise exception 'award_coins: مفيش وسام بالمرجع ده على حسابك';
      end if;

    when 'perfect_week' then
      -- بيتحقق من السجل نفسه: ٦ أيام مذاكرة على الأقل في آخر ٧ (٦ مش ٧ — الشرح في db/43).
      select count(distinct (l.created_at at time zone 'Africa/Cairo')::date)
        into v_days
        from public.coin_ledger l
       where l.user_id = v_uid
         and l.source in ('day_done', 'goal_done', 'badge')
         and l.source_type = 'earn'
         and l.created_at >= ((public.cairo_day() - 6)::timestamp
                              at time zone 'Africa/Cairo');

      if coalesce(v_days, 0) < 6 then
        raise exception
          'award_coins: الأسبوع الكامل محتاج ٦ أيام مذاكرة في آخر ٧ (عندك %)',
          coalesce(v_days, 0);
      end if;
      v_ref := v_day;

    when 'streak_day' then
      if not exists (
        select 1 from public.profiles p
         where p.id = v_uid
           and p.last_study_day = public.cairo_day()
           and coalesce(p.streak, 0) >= 2
      ) then
        raise exception 'award_coins: مفيش سلسلة شغّالة النهارده';
      end if;
      v_ref := v_day;

    -- ── محطات السلسلة (Phase 2) ────────────────────────────────────────
    /* الشرط `p.streak = N` بالمساواة مش >= : المحطة بتتصرف لحظة الوصول
       بالظبط، و`_streak_apply` بتناديها بعد ما تكتب الرقم الجديد. لو استخدمنا
       >= كان أي حد واصل ٣٠ يوم يقدر ياخد بونص اليوم الثالث كل يوم. */
    when 'streak_tier_3' then
      if not exists (
        select 1 from public.profiles p
         where p.id = v_uid
           and p.last_study_day = public.cairo_day()
           and coalesce(p.streak, 0) = 3
      ) then
        raise exception 'award_coins: بونص الـ٣ أيام محتاج سلسلة ٣ أيام النهارده';
      end if;
      v_ref := v_day;

    when 'streak_tier_30' then
      if not exists (
        select 1 from public.profiles p
         where p.id = v_uid
           and p.last_study_day = public.cairo_day()
           and coalesce(p.streak, 0) = 30
      ) then
        raise exception 'award_coins: بونص الشهر محتاج سلسلة ٣٠ يوم النهارده';
      end if;
      v_ref := v_day;

    when 'worship_prayer' then
      if v_ref is null or length(v_ref) < 12
         or v_ref !~ '^\d{4}-\d{2}-\d{2}-[a-z]+$' then
        raise exception 'award_coins: worship_prayer محتاج مرجع يوم-وصلاة صالح';
      end if;
      v_wday  := (left(v_ref, 10))::date;
      v_wname := substr(v_ref, 12);
      if v_wname not in ('fajr','dhuhr','asr','maghrib','isha') then
        raise exception 'award_coins: اسم صلاة غير مسموح: %', v_wname;
      end if;
      if not exists (
        select 1 from public.worship_progress w
         where w.user_id = v_uid
           and w.day = v_wday
           and (w.prayers ->> v_wname) = 'true'
      ) then
        raise exception 'award_coins: الصلاة دي مش متسجّلة على حسابك';
      end if;

    when 'worship_quran' then
      if v_ref is null or v_ref !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception 'award_coins: worship_quran محتاج مرجع تاريخ صالح';
      end if;
      v_wday := v_ref::date;
      if not exists (
        select 1 from public.worship_progress w
         where w.user_id = v_uid
           and w.day = v_wday
           and w.quran_ayahs >= coalesce((
                 select nullif(p.worship_settings ->> 'quran_daily_target', '')::int
                   from public.profiles p
                  where p.id = v_uid
               ), 10)
      ) then
        raise exception 'award_coins: هدف القرآن اليومي مش مكتمل على حسابك';
      end if;

    when 'worship_adhkar' then
      if v_ref is null or length(v_ref) < 12
         or v_ref !~ '^\d{4}-\d{2}-\d{2}-[a-z\-]+$' then
        raise exception 'award_coins: worship_adhkar محتاج مرجع يوم-وتصنيف صالح';
      end if;
      v_wday  := (left(v_ref, 10))::date;
      v_wname := substr(v_ref, 12);
      if v_wname not in ('morning','evening','after-prayer','sleep','general') then
        raise exception 'award_coins: تصنيف أذكار غير معروف: %', v_wname;
      end if;
      if not exists (
        select 1 from public.worship_progress w
         where w.user_id = v_uid
           and w.day = v_wday
           and coalesce((w.adhkar ->> v_wname)::int, 0) > 0
      ) then
        raise exception 'award_coins: الأذكار دي مش متسجّلة على حسابك';
      end if;

    else
      raise exception 'award_coins: المصدر % شغّال من غير تحقق حدث', p_source;
  end case;

  insert into public.coin_wallets (user_id) values (v_uid)
    on conflict (user_id) do nothing;

  perform 1 from public.coin_wallets where user_id = v_uid for update;

  if v_cap is not null then
    select count(*) into v_today_cnt
      from public.coin_ledger
     where user_id = v_uid
       and source  = p_source
       and source_type = 'earn'
       and created_at >= (public.cairo_day()::timestamp
                          at time zone 'Africa/Cairo');

    if v_today_cnt >= v_cap then
      v_capped := true;
    end if;
  end if;

  if not v_capped then
    insert into public.coin_ledger (user_id, source, amount, source_type, ref_id, metadata)
    values (v_uid, p_source, v_amount, 'earn', v_ref, coalesce(p_metadata, '{}'::jsonb))
    on conflict do nothing;

    if found then
      v_awarded := v_amount;
    end if;
  end if;

  return query
    select v_awarded,
           coalesce((select sum(l.amount)::int from public.coin_ledger l where l.user_id = v_uid), 0),
           v_capped;
end;
$function$

definitions.complete_study_day(uuid):
CREATE OR REPLACE FUNCTION public.complete_study_day(p_day_id uuid)
 RETURNS TABLE(xp_awarded integer, coins_awarded integer, new_xp integer, new_level integer, new_balance integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_xp_reward int;
  v_is_completed boolean;
  v_owner uuid;
  v_day_config uuid;
  v_new_xp int;
  v_new_level int;
  v_coins int := 0;
  v_balance int := 0;
  v_coin_result record;
begin
  if v_uid is null then
    raise exception 'complete_study_day: not authenticated';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'complete_study_day: anonymous not allowed — create account';
  end if;
  if p_day_id is null then
    raise exception 'complete_study_day: p_day_id required';
  end if;

  select xp_reward, is_completed, user_id, config_id
    into v_xp_reward, v_is_completed, v_owner, v_day_config
  from public.study_days
  where id = p_day_id
  for update;

  if not found then
    raise exception 'complete_study_day: day not found';
  end if;
  if v_owner != v_uid then
    raise exception 'complete_study_day: day does not belong to user';
  end if;

  -- idempotency: إذا مكتمل بالفعل، لا مكافأة إضافية ولا سلسلة جديدة
  if coalesce(v_is_completed, false) = true then
    select coalesce(xp,0) into v_new_xp from public.profiles where id = v_uid;
    v_new_level := floor(greatest(coalesce(v_new_xp,0),0) / 200) + 1;
    select coalesce(sum(amount),0)::int into v_balance from public.coin_ledger where user_id = v_uid;
    return query select 0::int, 0::int, v_new_xp::int, v_new_level::int, v_balance::int;
    return;
  end if;

  v_xp_reward := coalesce(v_xp_reward, 100);
  if v_xp_reward < 0 or v_xp_reward > 500 then
    raise exception 'complete_study_day: invalid xp_reward %', v_xp_reward;
  end if;

  update public.study_days set is_completed = true where id = p_day_id;

  perform set_config('app.xp_bypass', 'on', true);
  update public.profiles
  set xp = greatest(0, coalesce(xp,0) + v_xp_reward)
  where id = v_uid
  returning xp into v_new_xp;
  perform set_config('app.xp_bypass', 'off', true);

  if not found then
    raise exception 'complete_study_day: profile not found';
  end if;

  v_new_level := floor(greatest(v_new_xp,0) / 200) + 1;

  begin
    select awarded, balance into v_coins, v_balance
    from public.award_coins('day_done', p_day_id::text) limit 1;
  exception when others then
    v_coins := 0;
    select coalesce(sum(amount),0)::int into v_balance from public.coin_ledger where user_id = v_uid;
  end;

  /* 🔥 السلسلة بتتحرك هنا وبس: اليوم اتعلم مكتمل والـ XP والكوينز اتمنحوا
     فوق. مفيش أي مسار تاني بيغيّر profiles.streak (trigger بيقفل الكلاينت). */
  perform public._streak_apply(v_uid);

  return query select v_xp_reward::int, coalesce(v_coins,0)::int, v_new_xp::int, v_new_level::int, coalesce(v_balance,0)::int;
end;
$function$

definitions.claim_break_game(text):
CREATE OR REPLACE FUNCTION public.claim_break_game(p_game text)
 RETURNS TABLE(coins integer, xp integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid := auth.uid(); v_day date := public.cairo_day();
begin
  if v_uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then raise exception 'claim_break_game: سجّل حساب دائم للبريك'; end if;
  if p_game not in ('memory','reaction','quiz') then raise exception 'claim_break_game: لعبة غير معروفة'; end if;
  if p_game='quiz' and not exists(select 1 from public.break_quiz_sessions q where q.user_id=v_uid and q.day=v_day and q.solved_at is not null) then return query select 0,0,'أجب عن سؤال Quiz Rush المرتبط بمادتك أولًا'; return; end if;
  if not public.break_studied_today(v_uid) then return query select 0,0,'ذاكر أو خلّص هدف الأول — البريك مكافأة للمذاكرة'; return; end if;
  if (select count(*) from public.break_game_claims where user_id=v_uid and day=v_day) >= 2 then return query select 0,0,'وصلت حد مكافآت الألعاب النهارده'; return; end if;
  insert into public.break_game_claims(user_id,day,game) values(v_uid,v_day,p_game) on conflict do nothing;
  if not found then return query select 0,0,'أخدت مكافأة اللعبة دي النهارده'; return; end if;
  insert into public.coin_ledger(user_id,source,amount,source_type,ref_id,metadata) values(v_uid,'break_game',5,'earn',p_game||':'||v_day,jsonb_build_object('game',p_game));
  update public.profiles set xp=coalesce(profiles.xp,0)+10 where id=v_uid;
  return query select 5,10,'مبروك — ٥ كوين و١٠ XP ضمن حد النهارده';
end; $function$

definitions.answer_break_riddle(text):
CREATE OR REPLACE FUNCTION public.answer_break_riddle(p_answer text)
 RETURNS TABLE(correct boolean, attempts_left integer, coins integer, xp integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid := auth.uid(); v_day date := public.cairo_day(); v_session public.break_riddle_sessions%rowtype; v_answer text; v_coins int := 0; v_xp int := 0;
begin
  if v_uid is null then raise exception 'answer_break_riddle: لازم تكون داخل بحسابك'; end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then raise exception 'answer_break_riddle: سجّل حساب دائم للبريك'; end if;
  perform public.daily_break_riddle();
  select * into v_session from public.break_riddle_sessions where user_id=v_uid and day=v_day for update;
  if v_session.solved_at is not null then return query select true, 3-v_session.attempts, 0, 0, 'حلّيتها بالفعل النهارده'; return; end if;
  if v_session.attempts >= 3 then return query select false, 0, 0, 0, 'خلصت محاولات النهارده — ارجع بكرة'; return; end if;
  update public.break_riddle_sessions set attempts=attempts+1 where user_id=v_uid and day=v_day returning * into v_session;
  select answer into v_answer from public.break_riddles where id=v_session.riddle_id;
  if lower(trim(p_answer)) <> lower(trim(v_answer)) then return query select false, 3-v_session.attempts, 0, 0, 'إجابة قريبة؟ جرّب تاني'; return; end if;
  update public.break_riddle_sessions set solved_at=now() where user_id=v_uid and day=v_day;
  if public.break_studied_today(v_uid) then
    v_coins := case when now() - v_session.first_seen_at <= interval '5 minutes' then 20 else 15 end; v_xp := 20;
    insert into public.coin_ledger(user_id, source, amount, source_type, ref_id, metadata) values(v_uid,'break_riddle',v_coins,'earn','riddle:'||v_day,jsonb_build_object('riddle',v_session.riddle_id));
    update public.profiles set xp=coalesce(profiles.xp,0)+v_xp where id=v_uid;
  end if;
  return query select true, 3-v_session.attempts, v_coins, v_xp, case when v_coins>0 then 'صح! مكافأة بريك محدودة نزلت' else 'صح! ذاكر نشاطًا اليوم لتفتح مكافآت البريك' end;
end; $function$

definitions.solve_escape_step(text):
CREATE OR REPLACE FUNCTION public.solve_escape_step(p_answer text)
 RETURNS TABLE(correct boolean, step integer, attempts_left integer, coins integer, xp integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid := auth.uid(); v_day date := public.cairo_day(); s public.escape_sessions%rowtype; v_answer text; v_coins int:=0; v_xp int:=0;
begin
 if v_uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean,false) then raise exception 'solve_escape_step: سجّل حساب دائم أولًا'; end if;
 perform public.escape_room_status(); select * into s from public.escape_sessions where user_id=v_uid and day=v_day for update;
 if s.solved_at is not null then return query select true,4,6-s.attempts,0,0,'أنهيت الغرفة اليوم'; return; end if;
 if s.attempts >= 6 then return query select false,s.step::int,0,0,0,'انتهت محاولات اليوم — ارجع بكرة'; return; end if;
 update public.escape_sessions set attempts=attempts+1 where user_id=v_uid and day=v_day returning * into s;
 select ctx.answer into v_answer from public.escape_room_context(v_uid,s.config_id,s.step) ctx;
 if lower(trim(p_answer))<>lower(trim(v_answer)) then return query select false,s.step::int,6-s.attempts,0,0,'ليست الإجابة؛ استخدم التلميح وحاول ثانية'; return; end if;
 if s.step < 3 then update public.escape_sessions set step=step+1 where user_id=v_uid and day=v_day returning * into s; return query select true,s.step::int,6-s.attempts,0,0,'صحيح! فتحت اللغز التالي'; return; end if;
 update public.escape_sessions set step=4, solved_at=now() where user_id=v_uid and day=v_day;
 if public.break_studied_today(v_uid) then v_coins:=25; v_xp:=30; insert into public.coin_ledger(user_id,source,amount,source_type,ref_id,metadata) values(v_uid,'escape_room',v_coins,'earn','escape:'||v_day,'{}'); update public.profiles set xp=coalesce(profiles.xp,0)+v_xp where id=v_uid; end if;
 return query select true,4,6-s.attempts,v_coins,v_xp,case when v_coins>0 then 'هربت! كسبت ٢٥ كوين و٣٠ XP' else 'هربت! ذاكر اليوم لتفتح المكافأة' end;
end; $function$

definitions.claim_daily_mission(text):
CREATE OR REPLACE FUNCTION public.claim_daily_mission(p_mission text)
 RETURNS TABLE(coins integer, xp integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_uid uuid := auth.uid(); v_day date := public.cairo_day(); v_done boolean;
begin
  if v_uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then raise exception 'claim_daily_mission: سجّل حساب دائم أولًا'; end if;
  select dm.done into v_done from public.daily_missions() dm where dm.mission=p_mission;
  if not found then raise exception 'claim_daily_mission: مهمة غير معروفة'; end if;
  if not v_done then return query select 0,0,'أكمل المهمة الأول ثم استلم مكافأتها'; return; end if;
  insert into public.daily_mission_claims(user_id,day,mission) values(v_uid,v_day,p_mission) on conflict do nothing;
  if not found then return query select 0,0,'استلمت مكافأة المهمة دي بالفعل'; return; end if;
  insert into public.coin_ledger(user_id,source,amount,source_type,ref_id,metadata) values(v_uid,'daily_mission',5,'earn','mission:'||p_mission||':'||v_day,jsonb_build_object('mission',p_mission));
  update public.profiles set xp=coalesce(profiles.xp,0)+10 where id=v_uid;
  return query select 5,10,'تمت المهمة — ٥ كوين و١٠ XP';
end; $function$

definitions.sync_achievements():
CREATE OR REPLACE FUNCTION public.sync_achievements()
 RETURNS TABLE(achievement_id text, icon text, title text, requirement text, target integer, progress integer, coins integer, xp integer, unlocked boolean, unlocked_at timestamp with time zone, newly boolean, sort_order integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_days     int := 0;
  v_streak   int := 0;
  v_level    int := 1;
  v_badges   int := 0;
  v_courses  int := 0;
  v_new      text[] := '{}';
  v_row      public.achievements_catalog%rowtype;
  v_progress int;
begin
  if v_uid is null then
    raise exception 'sync_achievements: لازم تكون داخل بحسابك';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'sync_achievements: سجّل حساب دائم الأول';
  end if;

  -- الأرقام اللي الإنجازات بتقيس عليها — كلها من الداتابيز، مش من الكلاينت.
  select count(*) into v_days
    from public.study_days
   where user_id = v_uid and is_completed = true;

  select coalesce(streak, 0), (floor(greatest(coalesce(xp, 0), 0) / 200)::int + 1)
    into v_streak, v_level
    from public.profiles
   where id = v_uid;

  if not found then
    raise exception 'sync_achievements: profile not found';
  end if;

  select count(*) into v_badges
    from public.badges
   where user_id = v_uid;

  -- تراك كامل = كل مراحله مكتملة (نفس تعريف الواجهة: totalDays > 0 && completed >= total).
  select count(*) into v_courses
    from (
      select c.id
        from public.study_configs c
        join public.study_days d
          on d.config_id = c.id and d.user_id = c.user_id
       where c.user_id = v_uid
       group by c.id
      having count(*) > 0
         and count(*) filter (where d.is_completed) >= count(*)
    ) finished;

  for v_row in select * from public.achievements_catalog order by sort_order loop
    v_progress := case v_row.kind
      when 'days_done' then v_days
      when 'streak'    then v_streak
      when 'level'     then v_level
      when 'badges'    then v_badges
      when 'courses'   then v_courses
      else 0
    end;

    if v_progress < v_row.target then
      continue;
    end if;

    insert into public.user_achievements (user_id, achievement_id, coins, xp)
    values (v_uid, v_row.id, v_row.coins, v_row.xp)
    on conflict (user_id, achievement_id) do nothing;

    -- مفتاح الإنجاز لسه ما كانش موجود ⇒ ده أول مرة ⇒ استحق المكافأة.
    if found then
      v_new := array_append(v_new, v_row.id);

      if v_row.coins > 0 then
        /* المرجع مركّب من معرّف الإنجاز — الفهرس الفريد (user_id, source, ref_id)
           بيضمن إن الكوينز ما تتكررش حتى لو الدالة اتنادت في نفس اللحظة من
           تابّين. السقف اليومي مش مستخدم هنا لأن الإنجاز بيحصل مرة/حياة. */
        insert into public.coin_ledger (user_id, source, amount, source_type, ref_id, metadata)
        values (
          v_uid,
          'achievement',
          v_row.coins,
          'earn',
          'achievement:' || v_row.id,
          jsonb_build_object('achievement', v_row.id)
        )
        on conflict do nothing;
      end if;

      if v_row.xp > 0 then
        perform set_config('app.xp_bypass', 'on', true);
        update public.profiles
           set xp = greatest(0, coalesce(xp, 0) + v_row.xp)
         where id = v_uid;
        perform set_config('app.xp_bypass', 'off', true);
      end if;
    end if;
  end loop;

  return query
    select c.id,
           c.icon,
           c.title,
           c.requirement,
           c.target,
           (case c.kind
              when 'days_done' then v_days
              when 'streak'    then v_streak
              when 'level'     then v_level
              when 'badges'    then v_badges
              when 'courses'   then v_courses
              else 0
            end) as progress,
           c.coins,
           c.xp,
           (ua.user_id is not null) as unlocked,
           ua.unlocked_at,
           (c.id = any(v_new)) as newly,
           c.sort_order
      from public.achievements_catalog c
      left join public.user_achievements ua
        on ua.user_id = v_uid and ua.achievement_id = c.id
     order by c.sort_order;
end;
$function$

definitions.claim_weekly_mission():
CREATE OR REPLACE FUNCTION public.claim_weekly_mission()
 RETURNS TABLE(coins integer, xp integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_week  text := public.current_quiz_week();
  v_done  boolean;
  v_coins int;
  v_xp    int;
begin
  if v_uid is null or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'claim_weekly_mission: سجّل حساب دائم أولًا';
  end if;

  select wm.done, wm.coins, wm.xp into v_done, v_coins, v_xp
    from public.weekly_missions() wm
   where wm.id = 'weekly';

  if not found then
    raise exception 'claim_weekly_mission: مفيش مهمة أسبوعية';
  end if;
  if not v_done then
    return query select 0, 0, 'لسه ما كمّلتش شروط مهمة الأسبوع';
  end if;

  insert into public.weekly_mission_claims (user_id, week_key)
  values (v_uid, v_week)
  on conflict do nothing;

  if not found then
    return query select 0, 0, 'استلمت مكافأة الأسبوع ده بالفعل';
  end if;

  insert into public.coin_ledger (user_id, source, amount, source_type, ref_id, metadata)
  values (
    v_uid,
    'weekly_mission',
    v_coins,
    'earn',
    'weekly:' || v_week,
    jsonb_build_object('week', v_week)
  )
  on conflict do nothing;

  perform set_config('app.xp_bypass', 'on', true);
  update public.profiles
     set xp = greatest(0, coalesce(xp, 0) + v_xp)
   where id = v_uid;
  perform set_config('app.xp_bypass', 'off', true);

  return query select v_coins, v_xp, 'مبروك! مهمة الأسبوع خلصت 🎉';
end;
$function$

definitions.spin_wheel():
CREATE OR REPLACE FUNCTION public.spin_wheel()
 RETURNS TABLE(prize_id text, label text, coins integer, balance integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid   uuid := auth.uid();
  v_day   text := ((now() at time zone 'utc')::date)::text;
  v_id    text;
  v_label text;
  v_coins int;
  /* ⚠️ قرعة واحدة في متغير — نفس السبب المشروح بالتفصيل في `open_box`.
     هنا الباج كان بيرفع القيمة المتوقّعة من ١٨.٥ لـ ٣٦.١ كوين للفة،
     وجايزة الـ١٢٠ كانت بتطلع ١٧.٩٪ بدل ١٪. */
  v_roll  numeric;
begin
  if v_uid is null then
    raise exception 'spin_wheel: لازم تكون داخل بحسابك';
  end if;

  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'spin_wheel: العجلة للحسابات المسجّلة بس';
  end if;

  -- 🔒 قفل المحفظة: لفّتين في نفس اللحظة كانوا هيعدّوا الفحص سوا. الفهرس
  -- الفريد تحت بيمسك الحالة دي كمان، بس القفل بيخلّي التانية تستنى
  -- وتطلّع رسالة مفهومة بدل خطأ قيد.
  insert into public.coin_wallets (user_id) values (v_uid)
    on conflict (user_id) do nothing;
  perform 1 from public.coin_wallets where user_id = v_uid for update;

  if exists (
    select 1 from public.coin_ledger
     where user_id = v_uid and source = 'wheel'
       and source_type = 'earn' and ref_id = v_day
  ) then
    raise exception 'spin_wheel: لفّيت النهارده خلاص — تعالى بكرة';
  end if;

  -- شرط المذاكرة. مقصود إنه بعد فحص «لفّيت خلاص»: اللي لف بيعرف إنه لف،
  -- مش بيتقاله «ذاكر الأول».
  if not exists (
    select 1 from public.coin_ledger
     where user_id = v_uid
       and source in ('day_done', 'goal_done')
       and source_type = 'earn'
       -- مش `::timestamptz` — الشرح عند السقف اليومي في award_coins. هنا
       -- الغلط كان بيمنع لفة مستحقة: بأوفست سالب مذاكرة أول اليوم بـ UTC
       -- بتقع بره النافذة، فالعجلة تقول «ذاكر الأول» لواحد ذاكر فعلاً.
       and created_at >= (((now() at time zone 'utc')::date)::timestamp
                          at time zone 'utc')
  ) then
    raise exception 'spin_wheel: ذاكر حاجة النهارده الأول — العجلة مكافأة مذاكرة';
  end if;

  -- سحب موزون. نفس فكرة الصناديق: مجموع تراكمي وقرعة واحدة في السيرفر.
  v_roll := random();

  /* ⚠️⚠️ الأعمدة متسمّية `p_*` عن قصد — مش تنميق.

     `returns table (prize_id, label, coins, balance)` بيعرّف الأربعة دول
     **كمتغيّرات** في نطاق جسم الدالة كله. فـ `select id, label, coins`
     على `shop_wheel_prizes` (وفيها عمودين بالاسمين دول) بيرمي وقت
     التشغيل:

         column reference "label" is ambiguous

     ولاحظ إن `id` ماكانش بيشتكي لأن اسم الخروج `prize_id` مش `id` —
     يعني الفخ بيضرب الأعمدة اللي اتفق اسمها بس، وده اللي بيخليه يعدّي
     من المراجعة بالعين.

     نفس السبب اللي خلّى `open_box` تكتب `c.rarity as rar`. القاعدة:
     أي عمود في `returns table` اسمه زي عمود في جدول الاستعلام لازم
     يتغيّر اسمه في الاستعلام. التسمية هنا أأمن من التقييد بـ `cum.label`
     لأنها بتفضل صح لو حد ضاف CTE تاني أو غيّر الأسماء بعدين.

     ⚠️ أسماء الخروج نفسها ممنوع تتغيّر — `lib/shop/shop-data.ts` بيقرا
     `row.prize_id` و`row.label` بالحرف. */
  with cum as (
    select w.id    as p_id,
           w.label as p_label,
           w.coins as p_coins,
           sum(w.weight) over (order by w.id rows between unbounded preceding and current row) as upto,
           sum(w.weight) over () as total
      from public.shop_wheel_prizes w
  )
  select p_id, p_label, p_coins into v_id, v_label, v_coins
    from cum
   where upto >= v_roll * total
   order by upto
   limit 1;

  if v_id is null then
    raise exception 'spin_wheel: مفيش جوايز متسجّلة';
  end if;

  /* الفهرس الفريد على (user_id, source, ref_id) هو الحد الحقيقي: حتى لو
     الفحص فوق اتخطّى بأي طريقة، الصف التاني في نفس اليوم بيفشل. */
  insert into public.coin_ledger (user_id, source, amount, source_type, ref_id, metadata)
  values (v_uid, 'wheel', v_coins, 'earn', v_day, jsonb_build_object('prize', v_id));

  return query
    select v_id, v_label, v_coins,
           coalesce((select sum(amount) from public.coin_ledger where user_id = v_uid), 0)::int;
end;
$function$

definitions.open_box(text):
CREATE OR REPLACE FUNCTION public.open_box(p_box_id text)
 RETURNS TABLE(item_id text, rarity text, duplicate boolean, refunded integer, spent integer, balance integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_price    int;
  v_odds     jsonb;
  v_max_ref  int;
  v_balance  int;
  v_item     text;
  v_rarity   text;
  v_dup      boolean := false;
  v_refund   int := 0;
  /* ⚠️⚠️ القرعة **لازم** تتحسب في متغير قبل الاستعلام. `random()` دالة
     volatile، يعني لو اتكتبت جوه `where` بتتحسب **من جديد لكل صف** —
     فكل صف بياخد قرعة مستقلة بدل ما يكون فيه رقم واحد بيقع في المجموع
     التراكمي، والاحتمالات الناتجة مالهاش علاقة بالأوزان (الانحياز
     بيروح للصفوف الأول في `order by id`). ده كان باج حقيقي هنا:
     صندوق الورق كانت قيمته المتوقّعة ٣٢١ وسعره ٢٦٠ — **ميل بيت سالب**،
     يعني مضخة كوينز. ومفيش فحص في scripts/shop-seed.mjs يقدر يمسكه،
     لأن السكربت بيحسب رياضيات النية مش سلوك الاستعلام. */
  v_roll     numeric;
begin
  if v_uid is null then
    raise exception 'open_box: لازم تكون داخل بحسابك';
  end if;

  -- الزائر المجهول جلسته role = authenticated زي أي حد، فالتمييز لازم
  -- يبقى من التوكن نفسه. نفس فحص award_coins.
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'open_box: الصناديق للحسابات المسجّلة بس';
  end if;

  select price, odds into v_price, v_odds
    from public.shop_boxes where id = p_box_id;

  if not found then
    raise exception 'open_box: صندوق مش موجود: %', p_box_id;
  end if;

  -- 🔒 فحص المضخة. لاحظ إنه **قبل** الخصم: لو الإعدادات غلط، المستخدم
  -- ماينفعش يدفع أصلاً.
  select max(r.coins) into v_max_ref
    from public.shop_refunds r
   where coalesce((v_odds ->> r.rarity)::int, 0) > 0;

  if v_max_ref is not null and v_max_ref >= v_price then
    raise exception
      'open_box: إعدادات الصندوق % غلط — أقصى تعويض % والسعر %. الصندوق مقفول لحد ما يتصلّح.',
      p_box_id, v_max_ref, v_price;
  end if;

  insert into public.coin_wallets (user_id) values (v_uid)
    on conflict (user_id) do nothing;

  -- 🔒 نفس قفل purchase_item: طلبين في نفس اللحظة كانوا هيقروا نفس الرصيد
  -- ويفتحوا صندوقين بسعر واحد.
  perform 1 from public.coin_wallets where user_id = v_uid for update;

  select coalesce(sum(amount), 0)::int into v_balance
    from public.coin_ledger where user_id = v_uid;

  if v_balance < v_price then
    raise exception 'open_box: الرصيد مش كفاية (معاك % ومحتاج %)', v_balance, v_price;
  end if;

  /* السحب: وزن كل **عنصر** = وزن ندرته ÷ عدد عناصر الندرة المؤهّلة.

     يعني الوزن على الندرة مش على العنصر: إضافة عنصر أسطوري جديد بتقلّل
     فرصة كل عنصر أسطوري لوحده وبتسيب فرصة «تطلّع أسطوري» زي ما هي.

     والقسمة دي كمان بتحل مشكلة الندرة الفاضية لوحدها: ندرة بلا عناصر
     مؤهّلة مش بتدخل البركة خالص، فوزنها بيتوزّع على الباقي بالتناسب بدل
     ما السحب يقع في فراغ. */
  v_roll := random();

  with pool as (
    select c.id,
           c.rarity as rar,
           ((v_odds ->> c.rarity)::numeric
             / count(*) over (partition by c.rarity)) as w
      from public.shop_catalog c
     where c.price > 0
       and c.unlock is null
       and c.slot is not null
       and c.rarity is not null
       and coalesce((v_odds ->> c.rarity)::int, 0) > 0
  ),
  cum as (
    select id, rar,
           sum(w) over (order by id rows between unbounded preceding and current row) as upto,
           sum(w) over () as total
      from pool
  )
  select id, rar into v_item, v_rarity
    from cum
   where upto >= v_roll * total
   order by upto
   limit 1;

  if v_item is null then
    raise exception 'open_box: مفيش عناصر مؤهّلة في الصندوق ده دلوقتي';
  end if;

  v_dup := exists (
    select 1 from public.shop_inventory
     where user_id = v_uid and shop_inventory.item_id = v_item
  );

  -- الخصم أول حاجة بعد ما النتيجة بقت معروفة — والتمليك/التعويض بعده في
  -- نفس المعاملة.
  insert into public.coin_ledger (user_id, source, amount, source_type, ref_id, metadata)
  values (v_uid, 'box', -v_price, 'spend', p_box_id,
          jsonb_build_object('item', v_item, 'rarity', v_rarity, 'dup', v_dup));

  if v_dup then
    select coins into v_refund from public.shop_refunds where shop_refunds.rarity = v_rarity;
    v_refund := coalesce(v_refund, 0);

    -- الحزام والحمّالة: الفحص فوق على أقصى تعويض في الصندوق كله، وده على
    -- التعويض الفعلي. لو الاتنين اتخطّوا، المعاملة بترجع كلها.
    if v_refund >= v_price then
      raise exception 'open_box: تعويض % أكبر من سعر الصندوق % — مقفول', v_refund, v_price;
    end if;

    if v_refund > 0 then
      /* ⚠️ التعويض بيتكتب في السجل **مباشرة** مش عن طريق award_coins،
         لأن award_coins مبالغها ثابتة في coin_source_rules والتعويض
         بيختلف بالندرة. ده مقبول هنا وبس هنا: المبلغ جاي من جدول
         shop_refunds في السيرفر، والكلاينت ماله دعوة بيه.

         و`ref_id` بيفضل null عن قصد: الفهرس الفريد على (user_id, source,
         ref_id) بيغطّي صفوف الكسب اللي ليها مرجع، فلو حطّينا معرّف
         الصندوق هنا، تاني مكرر من نفس الصندوق كان هيفشل — والمستخدم يدفع
         ٢٦٠٠ وماياخدش لا عنصر ولا تعويض. */
      insert into public.coin_ledger (user_id, source, amount, source_type, metadata)
      values (v_uid, 'box_refund', v_refund, 'earn',
              jsonb_build_object('box', p_box_id, 'item', v_item, 'rarity', v_rarity));
    end if;
  else
    insert into public.shop_inventory (user_id, item_id) values (v_uid, v_item);
  end if;

  return query select v_item, v_rarity, v_dup, v_refund, v_price,
                      (v_balance - v_price + v_refund);
end;
$function$

definitions.purchase_item(text):
CREATE OR REPLACE FUNCTION public.purchase_item(p_item_id text)
 RETURNS TABLE(spent integer, balance integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_price   int;
  v_unlock  jsonb;
  v_balance int;
  v_disc    int  := 0;
  v_excl    boolean := false;
  v_in_day  boolean := false;
begin
  if v_uid is null then
    raise exception 'purchase_item: لازم تكون داخل بحسابك';
  end if;

  -- السعر من الجدول مش من الكلاينت. لو الكلاينت بعت السعر، أي حد يشتري
  -- أغلى عنصر بكوين واحد من الكونسول.
  select price, unlock into v_price, v_unlock
    from public.shop_catalog where id = p_item_id;

  if not found then
    raise exception 'purchase_item: عنصر مش موجود: %', p_item_id;
  end if;

  if exists (select 1 from public.shop_inventory
              where user_id = v_uid and item_id = p_item_id) then
    raise exception 'purchase_item: العنصر ده معاك بالفعل';
  end if;

  -- الشرط بيتحقق **في السيرفر** مش في الواجهة بس: إخفاء زرار مش حماية.
  --
  -- عرض النهارده بيتقرا هنا لسببين: الخصم، والاستثناء الوحيد لشرط الفتح.
  -- `perform` بيولّد عروض اليوم لو لسه، فمينفعش حد يشتري قبل التوليد
  -- ويلاقي الخصم مش موجود.
  perform public.ensure_daily_shop();

  select d.discount, d.exclusive into v_disc, v_excl
    from public.shop_daily d
   where d.day = (now() at time zone 'utc')::date
     and d.item_id = p_item_id;
  v_in_day := found;

  if not v_in_day then
    v_disc := 0;
    v_excl := false;
  end if;

  if v_unlock is not null and (v_unlock ->> 'kind') = 'daily' then
    /* العنصر الحصري. النوع 'daily' مش معروف لـ unlock_satisfied فبترجّع
       false دايماً — يعني العنصر ده **مقفول قفل دائم** والسطر ده هو
       الاستثناء الوحيد في المشروع كله. مكتوب صريح عشان لو اتشال، العنصر
       يقعد مقفول (فشل آمن) مش يتفتح للكل. */
    if not v_excl then
      raise exception 'purchase_item: العنصر ده بيتباع في المتجر اليومي بس';
    end if;
  elsif v_unlock is not null and not public.unlock_satisfied(v_uid, v_unlock) then
    raise exception 'purchase_item: العنصر لسه مقفول';
  end if;

  -- ⚠️ الخصم بيتحسب **هنا** من صف الجدول — مش بيتبعت من الواجهة. نفس سبب
  -- إن السعر نفسه بيتقرا من shop_catalog: أي رقم جاي من الكلاينت رقم
  -- بيتفاوض عليه.
  if v_disc > 0 then
    v_price := v_price - floor(v_price * v_disc / 100.0)::int;
  end if;

  insert into public.coin_wallets (user_id) values (v_uid)
    on conflict (user_id) do nothing;

  -- 🔒 القفل ده بيمنع الشرا المزدوج: طلبين في نفس اللحظة كانوا هيقروا نفس
  -- الرصيد ويخصموا الاتنين (عنصرين بسعر واحد). القفل على صف المحفظة
  -- بيخلّي التاني يستنى الأول، فيقرا الرصيد بعد الخصم.
  perform 1 from public.coin_wallets where user_id = v_uid for update;

  select coalesce(sum(amount), 0)::int into v_balance
    from public.coin_ledger where user_id = v_uid;

  if v_balance < v_price then
    raise exception 'purchase_item: الرصيد مش كفاية (معاك % ومحتاج %)', v_balance, v_price;
  end if;

  -- المجاني بياخد صف مخزن من غير حركة في السجل: القيد (amount <> 0) بيمنع
  -- حركة بصفر، وكمان سجل مليان أصفار مش سجل.
  if v_price > 0 then
    insert into public.coin_ledger (user_id, source, amount, source_type, ref_id)
    values (v_uid, 'purchase', -v_price, 'spend', p_item_id);
  end if;

  insert into public.shop_inventory (user_id, item_id) values (v_uid, p_item_id);

  return query select v_price, (v_balance - v_price);
end;
$function$

definitions.increment_xp(integer):
CREATE OR REPLACE FUNCTION public.increment_xp(p_delta integer)
 RETURNS TABLE(new_xp integer, new_level integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_new_xp int;
  v_level int;
begin
  if v_uid is null then
    raise exception 'increment_xp: not authenticated';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then
    raise exception 'increment_xp: anonymous not allowed — create account';
  end if;
  if p_delta is null then
    raise exception 'increment_xp: p_delta required';
  end if;
  if p_delta = 0 then
    raise exception 'increment_xp: p_delta cannot be 0';
  end if;
  -- حد صارم لمنع +999999: موجب حتى 200 (سقف Level واحد)، سالب حتى 500 (سماح للشراء)
  if p_delta < -500 or p_delta > 200 then
    raise exception 'increment_xp: p_delta out of range (-500..200), got %', p_delta;
  end if;

  -- bypass مؤقت للـ trigger (احتياطي إذا كان definer ما زال authenticated في بعض الإعدادات)
  perform set_config('app.xp_bypass', 'on', true);

  update public.profiles
  set xp = greatest(0, coalesce(xp, 0) + p_delta)
  where id = v_uid
  returning xp into v_new_xp;

  perform set_config('app.xp_bypass', 'off', true);

  if not found then
    raise exception 'increment_xp: profile not found for user %', v_uid;
  end if;

  v_level := floor(greatest(v_new_xp, 0) / 200) + 1;

  return query select v_new_xp, v_level;
end;
$function$
